import{c as e,Z as l,Q as u,j as r,m as n,o}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"九歌·国殇","description":"","frontmatter":{"title":"九歌·国殇","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/5.md","filePath":"books/shici/chuci/5.md"}'),s={name:"books/shici/chuci/5.md"};function h(q,i,c,p,d,_){const t=l("PoemAuthor"),a=l("PoemNav");return u(),r("div",null,[i[0]||(i[0]=n('<h1 id="九歌·国殇" tabindex="-1">九歌·国殇 <a class="header-anchor" href="#九歌·国殇" aria-label="Permalink to &quot;九歌·国殇&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>操吴戈兮被犀甲，车错毂兮短兵接。旌蔽日兮敌若云，矢交坠兮士争先。凌余阵兮躐余行，左骖殪兮右刃伤。霾两轮兮絷四马，援玉枹兮击鸣鼓。天时怼兮威灵怒，严杀尽兮弃原野。</p><p>出不入兮往不反，平原忽兮路超远。带长剑兮挟秦弓，首身离兮心不惩。诚既勇兮又以武，终刚强兮不可凌。身既死兮神以灵，子魂魄兮为鬼雄。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>国殇：为国捐躯的将士</li><li>操：手持</li><li>吴戈：吴国制造的戈，泛指锋利的武器</li><li>被：通&quot;披&quot;</li><li>犀甲：犀牛皮做的铠甲</li><li>车错毂：战车的车轮交错，形容战斗激烈</li><li>短兵：刀剑等短兵器</li><li>旌：旗帜</li><li>矢交坠：箭矢交相坠落</li><li>凌：侵犯</li><li>躐：践踏</li><li>行：行列</li><li>骖：驾车的马</li><li>殪：死亡</li><li>霾：通&quot;埋&quot;</li><li>絷：拴住</li><li>援：拿起</li><li>玉枹：玉饰的鼓槌</li><li>怼：怨恨</li><li>威灵：神灵</li><li>严杀：残酷的杀戮</li><li>忽：辽阔</li><li>超远：遥远</li><li>挟：夹在腋下</li><li>秦弓：秦国制造的弓，泛指良弓</li><li>首身离：身首异处</li><li>惩：恐惧</li><li>武：武艺</li><li>凌：侵犯</li><li>神以灵：精神不死</li><li>鬼雄：鬼中的英雄</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>手持吴戈身披犀甲，战车交错短兵相接。旗帜蔽日敌人如云，箭矢交相坠落将士争先。敌人侵犯我阵践踏我行，左骖战死右骖受伤。埋住车轮拴住马，拿起玉槌敲响战鼓。天怨神怒，残酷的杀戮后将士弃于原野。</p><p>出征不再归来，平原辽阔路途遥远。身带长剑腋下挟弓，身首分离心也不惧。确实勇敢又威武，始终刚强不可侵犯。身虽死精神不死，你们的魂魄是鬼中的英雄。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《九歌》中的一篇，是屈原为祭祀为国捐躯的将士所作的挽歌，是中国文学史上最早描写战争和歌颂烈士的作品。</p><p>上篇描写战争的激烈场面。&quot;操吴戈兮被犀甲&quot;，写将士的装束。&quot;车错毂兮短兵接&quot;，写战斗的激烈。&quot;旌蔽日兮敌若云&quot;，以夸张的手法写敌人之多。&quot;矢交坠兮士争先&quot;，写将士的英勇。</p><p>接着写战斗的残酷。&quot;凌余阵兮躐余行&quot;，写敌人进攻之猛。&quot;左骖殪兮右刃伤&quot;，写伤亡之惨重。&quot;霾两轮兮絷四马&quot;，写将士死战不退的决心。&quot;援玉枹兮击鸣鼓&quot;，写战至最后一刻的壮烈。</p><p>下篇歌颂烈士的精神。&quot;出不入兮往不反&quot;，写将士视死如归。&quot;带长剑兮挟秦弓，首身离兮心不惩&quot;，写将士虽死犹勇。&quot;诚既勇兮又以武，终刚强兮不可凌&quot;，直接赞美将士的勇敢和刚强。</p><p>最后&quot;身既死兮神以灵，子魂魄兮为鬼雄&quot;，是全诗的主旨所在。将士虽然身死，但精神不死，他们的魂魄是鬼中的英雄。这种对烈士精神的赞美，激励着后人为国捐躯。</p><p>全诗气势磅礴，情感激昂，将战争的残酷和烈士的英勇表现得淋漓尽致，是中国文学史上爱国主义的经典之作。</p>',17)),o(t,{name:"屈原",years:"约公元前340年－公元前278年",desc:"名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，“楚辞”的创立者和代表作家。代表作有《离骚》《九歌》《天问》等。",link:"/authors/quyuan"}),o(a)])}const b=e(s,[["render",h]]);export{f as __pageData,b as default};
